<div class="gm-upload" data-gm-upload="{{ $field }}" data-original="{{ $image }}"><div class="gm-upload-preview"><img @if($image) src="{{ $image }}" @else hidden @endif alt="{{ $label }}"><span @if($image) hidden @endif>{{ $field==='design_logo' ? 'Sin logotipo' : 'Sin fondo personalizado' }}</span></div><div><label>{{ $label }}<input type="file" @if($supported) name="{{ $field }}" @endif accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"></label><small>JPG, JPEG, PNG o WEBP · Hasta 4 MB</small><button type="button" data-gm-restore>Conservar imagen guardada</button><p role="status" aria-live="polite"></p></div></div>
